"""Independent deterministic AES-128 test vectors, generated by PyCryptodome."""
import argparse
import random
from pathlib import Path
from Crypto.Cipher import AES

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--output', type=Path, required=True)
args = parser.parse_args()
rng = random.Random(0x20260924)
rows = []
for _ in range(256):
    key = rng.getrandbits(128).to_bytes(16, 'big')
    plain = rng.getrandbits(128).to_bytes(16, 'big')
    cipher = AES.new(key, AES.MODE_ECB).encrypt(plain)
    rows.append((key + plain + cipher).hex())
args.output.write_text('\n'.join(rows) + '\n', encoding='ascii')
print('Generated 256 independent AES key/plaintext/ciphertext vectors')
